import math


def make_codebook(values, k=8):
    if k < 1:
        raise ValueError("a codebook needs at least one entry")
    ordered = sorted(values)
    if not ordered:
        raise ValueError("cannot build a codebook from nothing")
    if k == 1:
        return [ordered[len(ordered) // 2]]
    entries = []
    for index in range(k):
        position = index * (len(ordered) - 1) / (k - 1)
        low = int(math.floor(position))
        high = min(low + 1, len(ordered) - 1)
        weight = position - low
        entries.append(ordered[low] * (1 - weight) + ordered[high] * weight)
    return entries


def quantize(values, codebook):
    tokens = []
    for value in values:
        tokens.append(min(range(len(codebook)),
                          key=lambda index: abs(value - codebook[index])))
    return tokens


def rvq_encode(signal, codebooks):
    residual = list(signal)
    streams = []
    for codebook in codebooks:
        tokens = quantize(residual, codebook)
        streams.append(tokens)
        residual = [value - codebook[token]
                    for value, token in zip(residual, tokens)]
    return streams


def rvq_decode(streams, codebooks):
    if not streams:
        return []
    length = len(streams[0])
    out = [0.0] * length
    for tokens, codebook in zip(streams, codebooks):
        for index, token in enumerate(tokens):
            out[index] += codebook[token]
    return out


def rmse(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)) / len(a))


def softmax(logits, temperature=1.0):
    if temperature <= 0:
        raise ValueError("temperature must be positive")
    scaled = [value / temperature for value in logits]
    top = max(scaled)
    weights = [math.exp(value - top) for value in scaled]
    total = sum(weights)
    return [weight / total for weight in weights]


def entropy(probabilities):
    return -sum(p * math.log(p) for p in probabilities if p > 0)


def chunk_for_generation(sentences, max_seconds=13.0, seconds_per_char=0.06):
    chunks = []
    current = []
    used = 0.0
    for sentence in sentences:
        cost = len(sentence) * seconds_per_char
        if cost > max_seconds:
            raise ValueError(
                f"a single sentence needs {cost:.1f}s, over the "
                f"{max_seconds:.0f}s cap: {sentence!r}")
        if current and used + cost > max_seconds:
            chunks.append(current)
            current, used = [], 0.0
        current.append(sentence)
        used += cost
    if current:
        chunks.append(current)
    return chunks
